@Component("timeSeries-handler")
@ProcessingGroup("timeSeries-processing-group")
public class TimeSeriesEventHandler {
	
	// core constructor
	TimeSeriesEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTimeSeriesEvent
     */
    @EventHandler
    public void handle( CreateTimeSeriesEvent event) {
        entityManager.persist(new TimeSeries(event.getTimeSeriesId(), event.getName(), event.getTimezone(), event.getDatasets(), event.getForecasts(), event.getAnomalies(), event.getGranularity()));
    }

    /*
     * @param	event UpdateTimeSeriesEvent
     */
    @EventHandler
    public TimeSeries handle( UpdateTimeSeriesEvent event) {
    	entityManager.merge(new TimeSeries(event.getTimeSeriesId(), event.getName(), event.getTimezone(), event.getDatasets(), event.getForecasts(), event.getAnomalies(), event.getGranularity()));
    }
    
    /*
     * @param	event DeleteTimeSeriesEvent
     */
    @EventHandler
    public void on( DeleteTimeSeriesEvent event) {
    	TimeSeries entity = new TimeSeries();
   
    	// ------------------------------------------
    	// apply the TimeSeriesId
    	// ------------------------------------------
    	entity.setTimeSeriesId( event.getTimeSeriesId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TimeSeriesRepository timeSeriesEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TimeSeriesEventHandler.class.getName());

}
